!function(){var e=document.currentScript,t=e.getAttribute("data-id"),a="https://api.yourdomain.com/v1/track",n=Date.now();fetch(a+"/entry",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({client_id:t,url:window.location.href,referrer:document.referrer||"direct",screen_resolution:window.screen.width+"x"+window.screen.height,timestamp:(new Date).toISOString()}),keepalive:!0}).catch((e=>console.error("Tracking Error:",e))),document.addEventListener("visibilitychange",(function(){if("hidden"===document.visibilityState){var e=Math.round((Date.now()-n)/1e3),r=new Blob([JSON.stringify({client_id:t,url:window.location.href,duration:e,event_type:"exit"})],{type:"application/json"});navigator.sendBeacon(a+"/exit",r)}}))}();